	@Test
	void queryMaterializationPreservesFilterDistinctOrderAndGroupResults() {
		String namespace = "urn:materializer:query:";
		IRI predicate = FACTORY.createIRI(namespace, "value");
		IRI datatype = FACTORY.createIRI(namespace, "custom-datatype");
		IRI iriObject = FACTORY.createIRI(namespace, "iri-object");
		Literal blue = FACTORY.createLiteral("blue", datatype);
		Literal red = FACTORY.createLiteral("red", "en", Literal.BaseDirection.LTR);
		Literal ignored = FACTORY.createLiteral("ignore", datatype);

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.setNamespace("m", namespace);
			connection.add(FACTORY.createIRI(namespace, "s0"), predicate, blue);
			connection.add(FACTORY.createIRI(namespace, "s1"), predicate, blue);
			connection.add(FACTORY.createIRI(namespace, "s2"), predicate, red);
			connection.add(FACTORY.createIRI(namespace, "s3"), predicate, red);
			connection.add(FACTORY.createIRI(namespace, "s4"), predicate, iriObject);
			connection.add(FACTORY.createIRI(namespace, "s5"), predicate, ignored);
			connection.commit();
		}
		clearValueCaches();

		String distinctQuery = """
				PREFIX m: <urn:materializer:query:>
				SELECT DISTINCT ?o
				WHERE {
					?s m:value ?o .
					FILTER(STR(?o) != "ignore")
				}
				ORDER BY STR(?o)
				""";
		String groupQuery = """
				PREFIX m: <urn:materializer:query:>
				SELECT ?o (COUNT(?s) AS ?count)
				WHERE {
					?s m:value ?o .
					FILTER(STR(?o) != "ignore")
				}
				GROUP BY ?o
				ORDER BY STR(?o)
				""";

		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery distinct = connection.prepareTupleQuery(distinctQuery);
			distinct.setIncludeInferred(true);
			try (TupleQueryResult result = distinct.evaluate()) {
				assertTrue(result.hasNext());
				Literal actualBlue = (Literal) result.next().getValue("o");
				assertEquals("blue", actualBlue.stringValue());
				assertEquals(datatype.stringValue(), actualBlue.getDatatype().stringValue());
				assertTrue(actualBlue.getLanguage().isEmpty());

				assertTrue(result.hasNext());
				Literal actualRed = (Literal) result.next().getValue("o");
				assertEquals(red.stringValue(), actualRed.stringValue());
				assertEquals(red.getDatatype().stringValue(), actualRed.getDatatype().stringValue());
				assertEquals(red.getLanguage(), actualRed.getLanguage());
				assertEquals(red.getBaseDirection(), actualRed.getBaseDirection());

				assertTrue(result.hasNext());
				IRI actualIri = (IRI) result.next().getValue("o");
				assertEquals(iriObject.stringValue(), actualIri.stringValue());
				assertFalse(result.hasNext());
			}
			assertEquals(List.of(
					List.of("blue", "2"),
					List.of("red", "2"),
					List.of(iriObject.stringValue(), "1")), rows(connection, groupQuery, "o", "count"));
		}
	}

	@Test
	void nestedUnionOptionalMinusExistsVariantsSubqueryPreservesBindings() {
		String namespace = "urn:materializer:nested:";
		IRI kind = FACTORY.createIRI(namespace, "kind");
		IRI label = FACTORY.createIRI(namespace, "label");
		IRI tag = FACTORY.createIRI(namespace, "tag");
		IRI blocked = FACTORY.createIRI(namespace, "blocked");
		IRI suppressed = FACTORY.createIRI(namespace, "suppressed");
		IRI kindA = FACTORY.createIRI(namespace, "a");
		IRI kindB = FACTORY.createIRI(namespace, "b");
		IRI keep = FACTORY.createIRI(namespace, "keep");
		IRI yes = FACTORY.createIRI(namespace, "yes");

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.setNamespace("n", namespace);
			addNestedFixture(connection, namespace, kind, label, tag, blocked, suppressed, kindA, kindB, keep, yes);
			connection.commit();
		}
		clearValueCaches();

		String query = """
				PREFIX n: <urn:materializer:nested:>
				SELECT ?s ?label
				WHERE {
					{
						SELECT ?s ?label
						WHERE {
							{ ?s n:kind n:a } UNION { ?s n:kind n:b }
							OPTIONAL { ?s n:label ?label }
							FILTER EXISTS { ?s n:tag n:keep }
							FILTER NOT EXISTS { ?s n:suppressed n:yes }
							MINUS { ?s n:blocked n:yes }
						}
					}
				}
				ORDER BY STR(?s)
				""";

		try (RepositoryConnection connection = repository.getConnection()) {
			try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
				assertTrue(result.hasNext());
				BindingSet first = result.next();
				assertEquals("urn:materializer:nested:s1", first.getValue("s").stringValue());
				assertEquals("one", first.getValue("label").stringValue());

				assertTrue(result.hasNext());
				BindingSet second = result.next();
				assertEquals("urn:materializer:nested:s2", second.getValue("s").stringValue());
				assertEquals("two", second.getValue("label").stringValue());

				assertTrue(result.hasNext());
				BindingSet withoutLabel = result.next();
				assertEquals("urn:materializer:nested:s5", withoutLabel.getValue("s").stringValue());
				assertFalse(withoutLabel.hasBinding("label"));
				assertFalse(result.hasNext());
			}
		}
	}

